import re
from typing import List, Dict, Any, Tuple

# assumed helper functions
def node_by_title(doc: Dict, title: str) -> Dict | None:
    for node in doc.get("nodes", []):
        if node.get("title", "").strip() == title:
            return node
    return None

def node_by_id(doc: Dict, node_id: str) -> Dict | None:
    for node in doc.get("nodes", []):
        if node.get("node_id") == node_id:
            return node
    return None

def children(doc: Dict, node: Dict) -> List[Dict]:
    if not node:
        return []
    return [node_by_id(doc, cid) for cid in node.get("children", [])]

def table_rows(node: Dict) -> List[Tuple[int, Dict[str, str]]]:
    if node.get("kind") != "table":
        return []
    columns = node["table"]["columns"]
    rows = []
    for i, row in enumerate(node["table"]["rows"]):
        rows.append((i, dict(zip(columns, row))))
    return rows

def line_source(node: Dict, line_index: int) -> List[Any]:
    return [node["node_id"], line_index]

def row_source(node: Dict, row_index: int, cols: List[str]) -> List[Any]:
    return [node["node_id"], row_index, cols]

# ---------------------------------------------------------------------------

def _parse_object_line(line: str) -> Tuple[str, str]:
    """Parse a line from the Objects list into (id, description)."""
    m = re.match(r"Object (\d+):\s*(.+)", line)
    if m:
        num, desc = m.group(1), m.group(2).strip()
        return f"Object {num}", desc
    raise ValueError(f"Cannot parse object line '{line}'")

def _parse_event_line(line: str) -> List[str]:
    """Return a list of object IDs mentioned in the event line."""
    return [f"Object {m.group(1)}" for m in re.finditer(r"Object (\d+)", line)]

def _event_type(line: str) -> str | None:
    """Return a short event type or None if not relevant."""
    l = line.lower()
    if "enters the scene" in l:
        return "enter"
    if "exits the scene" in l:
        return "exit"
    if "collides with" in l:
        return "collision"
    if "is in view" in l or "in view" in l:
        return "view"  # handled as input
    return None

