def entities(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    """
    Return a list of entities in the given scope. Each entity is a dict
    with keys 'id' and 'description'.
    """
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    entities_set = {}
    # parse Objects list
    for child in children(doc, scope_node):
        if child.get("kind") == "list" and child.get("title", "").endswith(": Objects"):
            for line in child.get("lines", []):
                try:
                    oid, desc = _parse_object_line(line)
                    entities_set[oid] = desc
                except Exception:
                    continue
    # ensure all object ids seen in events or motion logs are included
    for child in children(doc, scope_node):
        if child.get("kind") == "list" and child.get("title", "").endswith(": Events"):
            for line in child.get("lines", []):
                for oid in _parse_event_line(line):
                    if oid not in entities_set:
                        entities_set[oid] = oid
        if child.get("kind") == "table" and child.get("title", "").endswith(": Motion log"):
            for _, row in table_rows(child):
                obj = row.get("object", "")
                # object cell is like '2 blue rubber cube'
                m = re.match(r"(\d+)\s+", obj)
                if m:
                    oid = f"Object {m.group(1)}"
                    if oid not in entities_set:
                        entities_set[oid] = oid

    # sort by numeric component
    def numeric_id(eid: str) -> Tuple[int, str]:
        m = re.match(r"Object (\d+)", eid)
        return (int(m.group(1)) if m else 0, eid)

    return sorted(
        [{"id": oid, "description": desc} for oid, desc in entities_set.items()],
        key=numeric_id,
    )

def recorded_end(doc: Dict, scope: str) -> float | None:
    """
    Return the last frame number recorded in the scope, or None if no time information.
    """
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return None

    last = None
    # Events
    for child in children(doc, scope_node):
        if child.get("kind") == "list" and child.get("title", "").endswith(": Events"):
            for line in child.get("lines", []):
                m = re.search(r"Frame (\d+)", line)
                if m:
                    frame = float(m.group(1))
                    if last is None or frame > last:
                        last = frame
    # Motion log
    for child in children(doc, scope_node):
        if child.get("kind") == "table" and child.get("title", "").endswith(": Motion log"):
            for _, row in table_rows(child):
                try:
                    frame = float(row["frame"])
                    if last is None or frame > last:
                        last = frame
                except Exception:
                    continue
    return last

def inputs(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    """
    Return a list of input records for the process in the given scope.
    """
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    inputs_out = []
    processed: Dict[Tuple[str, float], bool] = {}  # (object id, frame) -> True if input emitted

    # Helper to create an input from a motion log row
    def make_input_from_row(row_id: Tuple[str, int], frame: float, obj_id: str, row: Dict[str, str]):
        src = [row_source(row_id[0], row_id[1], ["frame", "object", "x", "y", "vx", "vy", "speed"])]
        inp = {
            "id": f"input_{obj_id.replace(' ', '_')}_{int(frame)}",
            "time": frame,
            "kind": "input",
            "entities": [obj_id],
            "fields": {
                "x": float(row["x"]),
                "y": float(row["y"]),
                "vx": float(row["vx"]),
                "vy": float(row["vy"]),
                "speed": float(row["speed"]),
            },
            "src": src,
        }
        inputs_out.append(inp)
        processed[(obj_id, frame)] = True

    # Map object id to list of motion log rows sorted by frame
    motion_rows: Dict[str, List[Tuple[int, str, Dict[str, str]]]] = {}
    for child in children(doc, scope_node):
        if child.get("kind") == "table" and child.get("title", "").endswith(": Motion log"):
            node_id = child["node_id"]
            for row_index, row in table_rows(child):
                try:
                    frame = float(row["frame"])
                    # object cell: '2 blue rubber cube'
                    m = re.match(r"(\d+)\s+", row["object"])
                    if not m:
                        continue
                    obj_id = f"Object {m.group(1)}"
                    motion_rows.setdefault(obj_id, []).append((row_index, node_id, row))
                except Exception:
                    continue

    # Process events for inputs
    for child in children(doc, scope_node):
        if child.get("kind") == "list" and child.get("title", "").endswith(": Events"):
            for line_index, line in enumerate(child.get("lines", [])):
                ft = re.search(r"Frame (\d+)", line)
                if not ft:
                    continue
                frame = float(ft.group(1))
                ev_type = _event_type(line)
                obj_ids = _parse_event_line(line)
                if ev_type == "enter":
                    # find the motion log row for this object at this frame
                    for obj_id in obj_ids:
                        # pick the closest frame row >= event frame
                        rows = motion_rows.get(obj_id, [])
                        chosen = None
                        for ridx, nid, row in rows:
                            if abs(float(row["frame"]) - frame) < 1e-6:
                                chosen = (ridx, nid, row)
                                break
                        if chosen and (obj_id, frame) not in processed:
                            make_input_from_row(chosen, frame, obj_id, chosen[2])
                if ev_type == "view":
                    # similar but treat as input at frame 0
                    for obj_id in obj_ids:
                        if (obj_id, 0.0) not in processed:
                            # first row in motion log
                            rows = motion_rows.get(obj_id, [])
                            if rows:
                                chosen = rows[0]
                                make_input_from_row(chosen, 0.0, obj_id, chosen[2])

    # Handle objects that appear only in motion log or earliest frames
    for obj_id, rows in motion_rows.items():
        # find earliest frame
        if not rows:
            continue
        rows_sorted = sorted(rows, key=lambda r: float(r[2]["frame"]))
        earliest_frame = float(rows_sorted[0][2]["frame"])
        if (obj_id, earliest_frame) not in processed:
            make_input_from_row(rows_sorted[0], earliest_frame, obj_id, rows_sorted[0][2])

    return inputs_out

def outcomes(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    """
    Return a list of outcome records for the process in the given scope.
    """
    scope_node = node_by_title(doc, scope)
