OBJ_LINE_RE = re.compile(r"Object (\d+):\s*(.+)")
EVENT_OBJ_RE = re.compile(r"Object (\d+)")
FRAME_RE = re.compile(r"Frame (\d+)")

def _parse_object_line(line: str) -> Tuple[str, str]:
    m = OBJ_LINE_RE.match(line)
    if not m:
        raise ValueError(f"cannot parse object line: {line!r}")
    num, desc = m.group(1), m.group(2).strip()
    return f"Object {num}", desc

def _parse_event_line(line: str) -> List[str]:
    return [f"Object {m.group(1)}" for m in EVENT_OBJ_RE.finditer(line)]

def _event_type(line: str) -> Optional[str]:
    l = line.lower()
    if "enters the scene" in l:          return "enter"
    if "exits the scene" in l:           return "exit"
    if "collides with" in l:             return "collision"
    if "in view" in l or "view" in l:    return "view"
    return None

