def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """External inputs into the process."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    inp_list: List[Dict[str, Any]] = []
    processed: Dict[Tuple[str, float], bool] = {}  # (obj_id, frame) -> True

    # Build motion rows per object
    motion_rows: Dict[str, List[Tuple[str, int, Dict[str, str]]]] = {}
    for child in children(doc, scope_node):
        if child.get("kind") == "table" and child.get("title", "").endswith(": Motion log"):
            node_id = child["node_id"]
            for row_index, row in table_rows(child):
                try:
                    frame_val = float(row["frame"])
                except Exception:
                    continue
                m = re.match(r"(\d+)\s+", row.get("object", ""))
                if not m:
                    continue
                oid = f"Object {m.group(1)}"
                motion_rows.setdefault(oid, []).append((node_id, row_index, row))

    def add_input(oid: str, frame: float, row: Tuple[str, int, Dict[str, str]], *, kind: str):
        n_id, r_idx, r = row
        src = [n_id, r_idx, ["frame", "object", "x", "y", "vx", "vy", "speed"]]
        try:
            f_val = float(r["frame"])
            x_val = float(r["x"])
            y_val = float(r["y"])
            vx_val = float(r["vx"])
            vy_val = float(r["vy"])
            sp_val = float(r["speed"])
        except Exception:
            # Skip malformed row
            return
        inp = {
            "id": f"input_{oid.replace(' ', '_')}_{int(f_val)}",
            "time": f_val,
            "kind": kind,
            "entities": [oid],
            "fields": {
                "x": x_val,
                "y": y_val,
                "vx": vx_val,
                "vy": vy_val,
                "speed": sp_val,
            },
            "src": src,
        }
        inp_list.append(inp)
        processed[(oid, f_val)] = True

    # Process Events for inputs
    for child in children(doc, scope_node):
        if child.get("kind") == "list" and child.get("title", "").endswith(": Events"):
            for l_idx, line in enumerate(child.get("lines", [])):
                m = FRAME_RE.search(line)
                if not m:
                    continue
                ev_frame = float(m.group(1))
                ev_type = _event_type(line)
                obj_ids = _parse_event_line(line)
                if ev_type == "enter":
                    for oid in obj_ids:
                        rows = motion_rows.get(oid, [])
                        # Find row with matching frame
                        for row_pair in rows:
                            n_id, r_idx, r = row_pair
                            if abs(float(r["frame"]) - ev_frame) < 1e-6:
                                add_input(oid, ev_frame, row_pair, kind="input")
                                break
                if ev_type == "view":
                    for oid in obj_ids:
                        rows = motion_rows.get(oid, [])
                        if rows:
                            n_id, r_idx, r = rows[0]
                            add_input(oid, ev_frame, (n_id, r_idx, r), kind="input")

    # Objects that only appear in motion logs or have first appearance not captured
    for oid, rows in motion_rows.items():
        if not rows:
            continue
        # choose earliest row
        rows_sorted = sorted(rows, key=lambda x: float(x[2]["frame"]))
        n_id, r_idx, r = rows_sorted[0]
        f_val = float(r["frame"])
        if (oid, f_val) not in processed:
            add_input(oid, f_val, (n_id, r_idx, r), kind="input")

    return inp_list

def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Events that the process produces."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    out_list: List[Dict[str, Any]] = []

    for child in children(doc, scope_node):
        if child.get("kind") == "list" and child.get("title", "").endswith(": Events"):
            for l_idx, line in enumerate(child.get("lines", [])):
                m = FRAME_RE.search(line)
                if not m:
                    continue
                f_val = float(m.group(1))
                ev_type = _event_type(line)
                if ev_type is None or ev_type in ("enter", "view"):
                    continue  # not generated by the process
                obj_ids = _parse_event_line(line)
                kind = ev_type  # collision or exit
                out_list.append({
                    "time": f_val,
                    "kind": kind,
                    "entities": obj_ids,
                    "value": None,
                    "src": [child["node_id"], l_idx],
                })

    return out_list

