    "enters the scene": "enter",
    "exits the scene": "exit",
    "collides with": "collision",
    "in view": "view",
    "view": "view",
}

def _parse_object_line(line: str) -> Tuple[str, str]:
    m = OBJ_LINE_RE.match(line)
