def _event_type(line: str) -> Optional[str]:
    l = line.lower()
    for key, val in EVENT_TYPES.items():
        if key in l:
            return val
    return None

def _numeric_id(eid: str) -> int:
    m = re.search(r"Object (\d+)", eid)
    return int(m.group(1)) if m else 0

