            node_id = child["node_id"]
            for row_idx, row in table_rows(child):
                m = re.match(r"(\d+)\s+", row.get("object", ""))
                if m:
                    oid = f"Object {m.group(1)}"
                    motion_by_obj.setdefault(oid, []).append((node_id, row_idx, row))

    # helper to create an input record
    def make_input(oid: str, row_info: Tuple[str, int, Dict[str, str]], kind: str):
        node_id, row_idx, row = row_info
        try:
            f = float(row["frame"])
            x = float(row["x"])
            y = float(row["y"])
            vx = float(row["vx"])
            vy = float(row["vy"])
            sp = float(row["speed"])
        except Exception:
            return
        if (oid, f) in seen:
            return
        seen.add((oid, f))
        inp.append({
            "id": f"input_{oid.replace(' ', '_')}_{int(f)}",
            "time": f,
            "kind": kind,
            "entities": [oid],
            "fields": {"x": x, "y": y, "vx": vx, "vy": vy, "speed": sp},
            "src": [[node_id, row_idx]],
        })

    # Process Events: ENTER or VIEW
    for child in children(doc, scope_node):
        if child.get("kind") == "list" and child.get("title", "").endswith(": Events"):
            for line_idx, line in enumerate(child.get("lines", [])):
                m = FRAME_RE.search(line)
                if not m:
                    continue
                f = float(m.group(1))
                etype = _event_type(line)
                obj_ids = _parse_event_line(line)
                if etype == "enter":
                    for oid in obj_ids:
                        # find matching frame in motion log
                        rows = motion_by_obj.get(oid, [])
                        for row_info in rows:
                            r_node, r_idx, r_row = row_info
                            if abs(float(r_row["frame"]) - f) < 1e-6:
                                make_input(oid, row_info, "enter")
                                break
                elif etype == "view":
                    for oid in obj_ids:
                        rows = motion_by_obj.get(oid, [])
                        if rows:
                            make_input(oid, rows[0], "view")

    # Objects that first appear only in motion log (no enter or view event)
    for oid, rows in motion_by_obj.items():
        if not rows:
            continue
        rows_sorted = sorted(rows, key=lambda r: float(r[2]["frame"]))
        make_input(oid, rows_sorted[0], "initial")

    return inp

def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    out: List[Dict[str, Any]] = []

    for child in children(doc, scope_node):
        if child.get("kind") == "list" and child.get("title", "").endswith(": Events"):
            for line_idx, line in enumerate(child.get("lines", [])):
                m = FRAME_RE.search(line)
                if not m:
                    continue
                f = float(m.group(1))
                etype = _event_type(line)
                if etype in ("enter", "view"):
                    continue  # not produced by process
                if not etype:
                    continue  # unknown
                obj_ids = _parse_event_line(line)
                out.append({
                    "time": f,
                    "kind": etype,
                    "entities": obj_ids,
                    "value": None,
                    "src": [[child["node_id"], line_idx]],
                })
    return out

